ALTER TABLE public.creator_registrations ADD COLUMN avatar_slug text NOT NULL DEFAULT 'explorer';
ALTER TABLE public.public_creators ADD COLUMN avatar_slug text NOT NULL DEFAULT 'explorer', ADD COLUMN avatar_name text NOT NULL DEFAULT 'Explorer', ADD COLUMN avatar_category text NOT NULL DEFAULT 'World Legends';
ALTER TABLE public.hire_requests ADD COLUMN website text;
CREATE OR REPLACE FUNCTION public.avatar_identity(slug text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT jsonb_build_object('name', CASE slug WHEN 'chang-e' THEN 'Chang''e' WHEN 'cu-chulainn' THEN 'Cú Chulainn' ELSE initcap(replace(slug,'-',' ')) END, 'category', CASE WHEN slug=ANY(string_to_array('krishna,arjuna,bhima,karna,draupadi,bhishma,abhimanyu,duryodhana,drona,eklavya',',')) THEN 'Mahabharata' WHEN slug=ANY(string_to_array('rama,sita,lakshmana,hanuman,ravana,jatayu,vibhishana,indrajit',',')) THEN 'Ramayana' WHEN slug=ANY(string_to_array('shiva,parvati,ganesha,vishnu,durga,kali,saraswati,lakshmi,kartikeya,indra',',')) THEN 'Indian Gods' WHEN slug=ANY(string_to_array('zeus,athena,poseidon,apollo,artemis,hermes,hades,odysseus,achilles',',')) THEN 'Greek' WHEN slug=ANY(string_to_array('odin,thor,loki,freyja,heimdall,tyr',',')) THEN 'Norse' WHEN slug=ANY(string_to_array('ra,anubis,horus,isis,thoth,bastet',',')) THEN 'Egyptian' WHEN slug=ANY(string_to_array('amaterasu,susanoo,raijin,kitsune',',')) THEN 'Japanese' WHEN slug=ANY(string_to_array('sun-wukong,nezha,chang-e,guan-yu',',')) THEN 'Chinese' WHEN slug=ANY(string_to_array('paul-bunyan,john-henry',',')) THEN 'Folk Heroes' ELSE 'World Legends' END) $$;
ALTER TABLE public.creator_registrations ADD CONSTRAINT known_creator_avatar CHECK(avatar_slug=ANY(string_to_array('explorer,krishna,arjuna,bhima,karna,draupadi,bhishma,abhimanyu,duryodhana,drona,eklavya,rama,sita,lakshmana,hanuman,ravana,jatayu,vibhishana,indrajit,shiva,parvati,ganesha,vishnu,durga,kali,saraswati,lakshmi,kartikeya,indra,zeus,athena,poseidon,apollo,artemis,hermes,hades,odysseus,achilles,odin,thor,loki,freyja,heimdall,tyr,ra,anubis,horus,isis,thoth,bastet,amaterasu,susanoo,raijin,kitsune,sun-wukong,nezha,chang-e,guan-yu,gilgamesh,ishtar,simurgh,merlin,the-morrigan,cu-chulainn,quetzalcoatl,tlaloc,anansi,shango,paul-bunyan,john-henry',',')));
CREATE OR REPLACE FUNCTION public.sync_public_creator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE identity jsonb; BEGIN identity:=public.avatar_identity(NEW.avatar_slug); INSERT INTO public.public_creators(public_id,creator_number,full_name,city_country,primary_speciality,ai_tools,experience_level,portfolio_link,avatar_url,created_at,is_visible,avatar_slug,avatar_name,avatar_category) VALUES(NEW.public_id,NEW.creator_number,identity->>'name',NEW.location,NEW.speciality,coalesce(NEW.tools,'{}'),NEW.experience,NEW.portfolio_url,NULL,NEW.created_at,NEW.is_visible,NEW.avatar_slug,identity->>'name',identity->>'category') ON CONFLICT(public_id) DO UPDATE SET full_name=EXCLUDED.full_name,city_country=EXCLUDED.city_country,primary_speciality=EXCLUDED.primary_speciality,ai_tools=EXCLUDED.ai_tools,experience_level=EXCLUDED.experience_level,portfolio_link=EXCLUDED.portfolio_link,avatar_url=NULL,is_visible=EXCLUDED.is_visible,avatar_slug=EXCLUDED.avatar_slug,avatar_name=EXCLUDED.avatar_name,avatar_category=EXCLUDED.avatar_category; RETURN NEW; END $$;
UPDATE public.public_creators SET full_name='Explorer',avatar_url=NULL,avatar_slug='explorer',avatar_name='Explorer',avatar_category='World Legends';
REVOKE SELECT ON public.public_creators FROM anon,authenticated;
GRANT SELECT(public_id,creator_number,avatar_slug,avatar_name,avatar_category,city_country,primary_speciality,ai_tools,experience_level,portfolio_link,created_at) ON public.public_creators TO anon,authenticated;
GRANT ALL ON public.public_creators TO service_role;
COMMENT ON COLUMN public.public_creators.full_name IS 'DEPRECATED: sanitized avatar alias only; no public access. Use avatar_name.';
COMMENT ON COLUMN public.public_creators.avatar_url IS 'DEPRECATED: private uploaded photos are never published. Use avatar_slug.';
COMMENT ON COLUMN public.creator_registrations.avatar_url IS 'DEPRECATED: replaced by mythic avatar_slug. Old private files remain owner-restricted.';